def transform(grid):
 g=[r[:] for r in grid]; h=len(g);w=len(g[0])
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 # Isolated blue pixels are noise.
 for r in range(h):
  for c in range(w):
   if grid[r][c]==1 and not any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1 for dr,dc in dirs):g[r][c]=0
 holes={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and sum(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1 for dr,dc in dirs)>=3}
 while holes:
  seed=holes.pop(); comp={seed}; stack=[seed]
  while stack:
   r,c=stack.pop()
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     q=(r+dr,c+dc)
     if q in holes:holes.remove(q);comp.add(q);stack.append(q)
  rs=[r for r,c in comp];cs=[c for r,c in comp]
  r0,r1,c0,c1=min(rs)-1,max(rs)+1,min(cs)-1,max(cs)+1
  for r in range(max(0,r0),min(h,r1+1)):
   for c in range(max(0,c0),min(w,c1+1)):
    if grid[r][c]==1 and (r in (r0,r1) or c in (c0,c1)):g[r][c]=7
 return g
